{
  "Q1": {
    "q1a_rule": {
      "rationale": "Identifies 2026-15665, 91 FR 49178–49227, both required dates, docket OPM-2025-0107 and RIN 3206-AO86.",
      "verdict": "yes"
    },
    "q1b_nprm": {
      "rationale": "Identifies 2026-04377, 91 FR 10904, published March 5, 2026.",
      "verdict": "yes"
    },
    "q1c_first": {
      "rationale": "Lists 2026-17335 with publication August 25, effectiveness September 2, and describes typographical and clerical corrections to instructions and regulatory text.",
      "verdict": "yes"
    },
    "q1c_second": {
      "rationale": "Lists 2026-18800, published and effective September 15, and explains restoration of the inadvertently removed CTAP definition subparagraphs.",
      "verdict": "yes"
    },
    "q1d_applicability": {
      "rationale": "Correctly uses notice issuance before versus on or after September 2 and locates the rule in DATES and the implementation preamble.",
      "verdict": "yes"
    },
    "q1e_appeals": {
      "rationale": "Lists 2026-15666, effective September 2 and in force, and describes its replacement of subpart I.",
      "verdict": "yes"
    },
    "q1e_leave": {
      "rationale": "Lists 2026-21320, its revision of §351.806, November 18 effective date, and not-yet-in-force status.",
      "verdict": "yes"
    },
    "q1e_senior": {
      "rationale": "Lists 2026-21316, amendments to §§351.203 and 351.503, November 18 effective date, and not-yet-in-force status.",
      "verdict": "yes"
    },
    "q1_cite": {
      "rationale": "Document numbers, FR pages and relevant provisions support the substantial factual claims.",
      "verdict": "no"
    },
    "q1_fab": {
      "rationale": "No invented source or unsupported attribution is established; the identified documents and principal provisions match the key.",
      "verdict": "no"
    }
  },
  "Q2": {
    "q2a_abbott": {
      "rationale": "Gives 7+5+5=17, zero preference points and total 17.",
      "verdict": "yes"
    },
    "q2a_bianchi": {
      "rationale": "Gives 5+0+3=8, plus five preference points, total 13.",
      "verdict": "yes"
    },
    "q2a_castillo": {
      "rationale": "Gives performance and total 17 with zero preference points, explaining the retirement restrictions under §351.504(b).",
      "verdict": "yes"
    },
    "q2a_dalton": {
      "rationale": "Calculates proxy (7+0)/2=3.5, performance 10.5 and total 13.5 after three preference points.",
      "verdict": "yes"
    },
    "q2a_eze": {
      "rationale": "Gives total 15 with zero preference points and correctly places Eze in tenure subgroup II.",
      "verdict": "yes"
    },
    "q2a_fontaine": {
      "rationale": "Uses the one-rating rule, 5×3=15, with total 15.",
      "verdict": "yes"
    },
    "q2b_order": {
      "rationale": "Gives Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi; explains Abbott's earlier SCD and Fontaine's superior tenure subgroup.",
      "verdict": "yes"
    },
    "q2b_released": {
      "rationale": "Explicitly identifies Bianchi and Dalton as released.",
      "verdict": "yes"
    },
    "q2c_old": {
      "rationale": "Says Bianchi formerly ranked above Abbott because AD preceded B within tenure group I, relying on the final preamble's descriptions and examples.",
      "verdict": "yes"
    },
    "q2d_records": {
      "rationale": "Provides access to the complete register with other employees' names, her augmented performance credit and SCD, and relevant additional registers under §351.506.",
      "verdict": "yes"
    },
    "q2_cite": {
      "rationale": "The scoring, ordering, retirement treatment and records discussion have CFR and FR citations.",
      "verdict": "no"
    },
    "q2_fab": {
      "rationale": "No fabricated source is established; the qualified reading of the singular records language is expressly accepted by the key.",
      "verdict": "no"
    }
  },
  "Q3": {
    "q3a_case_a": {
      "rationale": "Correctly gives no preference eligibility, zero points and subgroup B, with the retirement and rank restrictions.",
      "verdict": "yes"
    },
    "q3a_case_b": {
      "rationale": "Correctly applies §351.504(b)(4): disability alone is insufficient without meeting (b)(1), (2) or (3); gives zero points and subgroup B.",
      "verdict": "yes"
    },
    "q3a_case_c": {
      "rationale": "Gives preference eligibility, five points and subgroup AD based on combat-related disability retirement and the major-rank condition.",
      "verdict": "yes"
    },
    "q3a_case_d": {
      "rationale": "Gives no preference eligibility, zero points and subgroup B because none of the retirement exceptions applies.",
      "verdict": "yes"
    },
    "q3a_case_e": {
      "rationale": "Correctly relies on retirement before 20 years and rank below major; gives three points and subgroup A.",
      "verdict": "yes"
    },
    "q3b_scd_a": {
      "rationale": "Credits two campaign years and calculates September 7, 2010 minus two years as September 7, 2008.",
      "verdict": "yes"
    },
    "q3b_scd_c": {
      "rationale": "Credits all 14 active-service years and calculates September 7, 1996.",
      "verdict": "yes"
    },
    "q3c_labels": {
      "rationale": "Explains that AD/A/B identify employees rather than form ranking tiers; preference operates through added points.",
      "verdict": "yes"
    },
    "q3_cite": {
      "rationale": "The answer supplies deciding paragraphs and FR locations throughout.",
      "verdict": "no"
    },
    "q3_fab": {
      "rationale": "No invented source or provision is established; the additional interpretive reservations do not fabricate authority.",
      "verdict": "no"
    }
  },
  "Q4": {
    "q4a_farah": {
      "rationale": "Selects the three most recent ratings, valued 7, 3 and 3, giving 13.",
      "verdict": "yes"
    },
    "q4b_cutoff_date": {
      "rationale": "Calculates September 3 minus 45 days as July 20, 2026 and shows the day arithmetic.",
      "verdict": "yes"
    },
    "q4b_credit": {
      "rationale": "Excludes the August rating and gives 3+3+5=11.",
      "verdict": "yes"
    },
    "q4c_not_on_record": {
      "rationale": "Says no because the rating was unavailable to the register office until after the cutoff, citing §351.503(c)(2)–(3).",
      "verdict": "yes"
    },
    "q4d_gina": {
      "rationale": "Excludes August 2022, calculates proxy four from values five and three, and gives total 12.",
      "verdict": "yes"
    },
    "q4e_modal": {
      "rationale": "Applies §351.503(f)(1)'s modal-rating requirement for the position's summary-level pattern.",
      "verdict": "yes"
    },
    "q4e_flag": {
      "rationale": "Explicitly flags both the unprinted modal-rating definition and the absence of a formula converting it to points.",
      "verdict": "yes"
    },
    "q4_cite": {
      "rationale": "The calculations and missing-rating treatment are supported by specific CFR paragraphs and FR pages.",
      "verdict": "no"
    },
    "q4_fab": {
      "rationale": "No fabricated authority is established; the answer appropriately declines to supply the unprinted definition.",
      "verdict": "no"
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "rationale": "Applies the earlier rules because the August 28 notice preceded September 2, regardless of the October effective date.",
      "verdict": "yes"
    },
    "q5a_i_result": {
      "rationale": "Uses 12 and 20 years of credit, obtaining Lee's 1986 and Park's 1999 adjusted dates, and releases Park.",
      "verdict": "yes"
    },
    "q5a_ii": {
      "rationale": "Applies the amended rules on September 2 and releases Lee based on nine versus 21 points.",
      "verdict": "yes"
    },
    "q5a_iii": {
      "rationale": "Applies the amended rules on September 3 and releases Lee.",
      "verdict": "yes"
    },
    "q5b_no_recalc": {
      "rationale": "Explicitly cites §351.805(b) and explains why a notice solely delaying effectiveness does not require recalculation.",
      "verdict": "yes"
    },
    "q5c_version": {
      "rationale": "Identifies agency notice issuance as the event fixing the applicable regulatory version and cites DATES and implementation.",
      "verdict": "yes"
    },
    "q5c_window": {
      "rationale": "Identifies notice issuance, or the agency cutoff when used, as the end of the ratings period.",
      "verdict": "yes"
    },
    "q5c_standing": {
      "rationale": "Correctly distinguishes receipt of the specific notice as fixing tenure subgroup and retention standing.",
      "verdict": "yes"
    },
    "q5_cite": {
      "rationale": "Provides the relevant preamble locations and CFR provisions for every material conclusion.",
      "verdict": "no"
    },
    "q5_fab": {
      "rationale": "No invented source is established; the earlier-rules arithmetic is expressly grounded in the final preamble.",
      "verdict": "no"
    }
  },
  "Q6": {
    "q6a_reach": {
      "rationale": "Correctly includes positions 1–3 and excludes 4 for grade distance, 5 for higher standing, 6 for schedule and 7 for competitive area.",
      "verdict": "yes"
    },
    "q6a_offer": {
      "rationale": "Requires the GS-12 Ellis position as the least reduction in representative rate.",
      "verdict": "yes"
    },
    "q6b_five": {
      "rationale": "States the five-grade limit, includes GS-9 Hana, and retains GS-12 Ellis as the required offer.",
      "verdict": "yes"
    },
    "q6c_level1": {
      "rationale": "Says no assignment right at Level 1 because §351.701(a) requires Level 2 or higher.",
      "verdict": "yes"
    },
    "q6d_excepted": {
      "rationale": "Explains that excepted-service rights depend on the agency's discretionary adoption under §351.705(a).",
      "verdict": "yes"
    },
    "q6e_level2": {
      "rationale": "Expressly identifies elimination of former §351.701(d)'s restriction on Level 2 employees displacing higher-rated holders.",
      "verdict": "yes"
    },
    "q6e_bump": {
      "rationale": "Describes replacement of bump and retreat with a single assignment right against lower-standing holders.",
      "verdict": "yes"
    },
    "q6_cite": {
      "rationale": "Specific assignment provisions and the relevant final-preamble pages support the answer.",
      "verdict": "no"
    },
    "q6_fab": {
      "rationale": "No invented source is established; the material assignment rules match the key.",
      "verdict": "no"
    }
  },
  "Q7": {
    "q7a_mspb": {
      "rationale": "Selects MSPB because the August 31 notice preceded the appeals rule's September 2 notice-date applicability boundary.",
      "verdict": "yes"
    },
    "q7a_board_rule": {
      "rationale": "Cites 2026-16456, 91 FR 51997, and quotes its commitment to accept cases noticed before the effective date.",
      "verdict": "yes"
    },
    "q7b_opm": {
      "rationale": "Selects OPM for the October 19 notice and cites §351.901(a).",
      "verdict": "yes"
    },
    "q7b_count": {
      "rationale": "Counts December 19 as day one, January 17 as day 30, and applies the weekend/holiday extension.",
      "verdict": "yes"
    },
    "q7b_date": {
      "rationale": "Gives Tuesday, January 19, 2027 because January 18 is the Martin Luther King Jr. federal holiday.",
      "verdict": "yes"
    },
    "q7b_efile": {
      "rationale": "Requires OPM's identified electronic system and gives the 11:59 p.m. Eastern deadline.",
      "verdict": "yes"
    },
    "q7c_burden": {
      "rationale": "Places the preponderance burden on Morgan to prove a RIF-law or regulation violation and resulting prejudice, along with timeliness and jurisdiction.",
      "verdict": "yes"
    },
    "q7c_hearing": {
      "rationale": "Says there is no hearing entitlement; review is written unless OPM finds a hearing necessary and efficient.",
      "verdict": "yes"
    },
    "q7d_text": {
      "rationale": "States exclusivity and the express prohibition on negotiated grievances and grievance arbitration under §351.901(c).",
      "verdict": "yes"
    },
    "q7d_flag": {
      "rationale": "Reports that existing CBAs are not retroactively invalidated and that particular existing-agreement disputes remain with chapter 71 forums.",
      "verdict": "yes"
    },
    "q7e_court": {
      "rationale": "Quotes the judicial-review prohibition and cites the absence of further appeal under §351.909(e).",
      "verdict": "yes"
    },
    "q7f_tolling": {
      "rationale": "Applies §351.902(b)(3), identifies OSC and material effect, and calculates April 9, 2027 from March 10 finality.",
      "verdict": "yes"
    },
    "q7g_where": {
      "rationale": "Precisely locates applicability in DATES and the preamble, and quotes the explanation that §351.901 contains no separate applicability note.",
      "verdict": "yes"
    },
    "q7_cite": {
      "rationale": "The answer consistently supplies document numbers, provisions and FR locations.",
      "verdict": "no"
    },
    "q7_fab": {
      "rationale": "No fabricated source is established; the Board's inconsistent triggers are real and are appropriately distinguished.",
      "verdict": "no"
    }
  },
  "Q8": {
    "q8a_adopted": {
      "rationale": "Identifies 2026-21320, revised §351.806, and November 18 effectiveness, distinguishing the current period from the adopted future text.",
      "verdict": "yes"
    },
    "q8a_new_text": {
      "rationale": "Provides the ordinary-duty-status rule and permission for appropriate administrative leave consistent with part 630, subpart N.",
      "verdict": "yes"
    },
    "q8a_today": {
      "rationale": "Describes the current rule's 'when possible' duty-status requirement using the rulemaking documents.",
      "verdict": "yes"
    },
    "q8b_consent": {
      "rationale": "Says consent is unnecessary under adopted §§351.806(b) and 630.1403(c)(10).",
      "verdict": "yes"
    },
    "q8b_cap": {
      "rationale": "Explains that (c)(10) has no express numeric cap and distinguishes the preamble's 12-week limit for (c)(9) and (c)(11).",
      "verdict": "yes"
    },
    "q8b_flag": {
      "rationale": "The uncertainty field expressly questions whether the broader workforce-realignment 12-week language reaches (c)(10); the future effective date is also clear.",
      "verdict": "yes"
    },
    "q8c_guidance": {
      "rationale": "Names the July 30, 2025 template, CPM 2025-12, and describes its authorization for leave between separation notice and effectiveness.",
      "verdict": "yes"
    },
    "q8d_no_effect": {
      "rationale": "Explains that paid non-duty status does not alter substantive or procedural RIF rights, competition, registers or appeals.",
      "verdict": "yes"
    },
    "q8_cite": {
      "rationale": "The answer supports current and future text, guidance and limitations with FR and CFR citations.",
      "verdict": "no"
    },
    "q8_fab": {
      "rationale": "No invented source is established; the answer appropriately qualifies what was not printed in the reviewed documents.",
      "verdict": "no"
    }
  },
  "Q9": {
    "q9_s1": {
      "rationale": "Finds noncompliance because 57 days is within 90 and requires an OPM submission and advance approval under §351.402(c).",
      "verdict": "yes"
    },
    "q9_s3": {
      "rationale": "Distinguishes supervisory probation from initial probation and requires Ortiz to be ranked as a competing employee.",
      "verdict": "yes"
    },
    "q9_s4": {
      "rationale": "Calculates the September 13 cutoff, excludes the October 2 rating and also identifies inconsistent application.",
      "verdict": "yes"
    },
    "q9_s5": {
      "rationale": "Uses proxy (7+5)/2=6 and total 18 rather than a presumed Level 3.",
      "verdict": "yes"
    },
    "q9_s6": {
      "rationale": "Correctly rejects extra points under a single five-level pattern, notwithstanding an advance written policy.",
      "verdict": "yes"
    },
    "q9_s8": {
      "rationale": "Applies §351.602(a)'s prohibition on retaining a specifically limited temporary-promotion holder while releasing a competing employee.",
      "verdict": "yes"
    },
    "q9_s10": {
      "rationale": "Requires job-related demonstration and job analysis, and rejects solely or principally automated self-assessment.",
      "verdict": "yes"
    },
    "q9_s11": {
      "rationale": "Explicitly states that temporary exceptions stand alone and cannot be sequenced or stacked.",
      "verdict": "yes"
    },
    "q9_s12": {
      "rationale": "Corrects the appeal forum to OPM and cites both the notice-content provision and notice-date applicability.",
      "verdict": "yes"
    },
    "q9_ok": {
      "rationale": "Calls steps 2, 7 and 9 in order and supplies the deciding provision for each.",
      "verdict": "yes"
    },
    "q9_false2": {
      "rationale": "Calls step 2 in order, not a violation.",
      "verdict": "no"
    },
    "q9_false7": {
      "rationale": "Calls step 7 in order and permits selection among fully tied employees.",
      "verdict": "no"
    },
    "q9_false9": {
      "rationale": "Calls step 9 in order under the five-year assessment exemption.",
      "verdict": "no"
    },
    "q9_cite": {
      "rationale": "Each step has relevant CFR citations, supplemented by document numbers and FR pages.",
      "verdict": "no"
    },
    "q9_fab": {
      "rationale": "No invented source is established; the cited substantive provisions match the key.",
      "verdict": "no"
    }
  },
  "Q10": {
    "q10a_gap": {
      "rationale": "States that only the introductory text remained and explains how instruction 11 removed (1)(i) and (1)(ii) effective September 2.",
      "verdict": "yes"
    },
    "q10b_doc": {
      "rationale": "Identifies 2026-18800, 91 FR 58363, published and effective September 15, as restoring both subparagraphs.",
      "verdict": "yes"
    },
    "q10b_reason": {
      "rationale": "Gives good cause, no substantive change, restoration of text not proposed for removal, and the same basis for immediate effectiveness.",
      "verdict": "yes"
    },
    "q10c_lower": {
      "rationale": "Correctly retains displaced status after declining a lower-rate offer and explains the same-schedule, equal-or-higher-rate condition.",
      "verdict": "yes"
    },
    "q10c_same": {
      "rationale": "Correctly says declining the same-rate full-time offer ends status under (1)(i).",
      "verdict": "yes"
    },
    "q10_cite": {
      "rationale": "The answer cites instruction 11, the definition and the correcting amendment's FR pages.",
      "verdict": "no"
    },
    "q10_fab": {
      "rationale": "No fabricated source or unsupported attribution is established.",
      "verdict": "no"
    }
  },
  "Q11": {
    "q11_valid_10": {
      "rationale": "38 distinct units count: #1; #2 (three paragraphs); #3; #4 (two); #5–7; #9–11; #12–13 (four paragraphs, merging §351.502(a)(3)); #14 (four); #15 (three); #16–25 (ten); #26 (three); #27. Exclude #8's corrected errors/citation wording. The threshold is met.",
      "verdict": "yes"
    },
    "q11_valid_16": {
      "rationale": "The same 38 qualify: #1; #2×3; #3; #4×2; #5–7; #9–11; #12–13×4 with duplicate paragraph merged; #14×4; #15×3; #16–25; #26×3; #27. This exceeds 16.",
      "verdict": "yes"
    },
    "q11_valid_22": {
      "rationale": "The same 38 qualify: #1; #2×3; #3; #4×2; #5–7; #9–11; #12–13×4 with duplicate paragraph merged; #14×4; #15×3; #16–25; #26×3; #27. This exceeds 22.",
      "verdict": "yes"
    },
    "q11_valid_28": {
      "rationale": "The same 38 qualify: #1; #2×3; #3; #4×2; #5–7; #9–11; #12–13×4 with duplicate paragraph merged; #14×4; #15×3; #16–25; #26×3; #27. This exceeds 28.",
      "verdict": "yes"
    },
    "q11_valid_34": {
      "rationale": "The same 38 qualify: #1; #2×3; #3; #4×2; #5–7; #9–11; #12–13×4 with duplicate paragraph merged; #14×4; #15×3; #16–25; #26×3; #27. Tool checks confirmed the multiple timing and performance-reference paragraphs. This exceeds 34.",
      "verdict": "yes"
    },
    "q11_deep": {
      "rationale": "At least ten listed categories are covered: notice timing; Level 2 terminology; mandatory subgroup identifiers; retiree cross-reference; records/access wording; assessments; notice wording; transfer procedures; CTAP subpart; and historical rating-pattern references.",
      "verdict": "yes"
    },
    "q11_cite": {
      "rationale": "Every comparison identifies a provision or definition, with both documents and their regulatory-text page ranges supplied.",
      "verdict": "no"
    },
    "q11_fab": {
      "rationale": "No invented source is established. Item 8 reports actual first-print errors but does not count because the correction restored the proposed text.",
      "verdict": "no"
    }
  },
  "Q12": {
    "q12_quinn": {
      "rationale": "Excludes Quinn from the register because of initial probation and expressly recognizes the agency's authority to keep her.",
      "verdict": "yes"
    },
    "q12_ab": {
      "rationale": "Gives Alvarez 19 with no preference points, and Brandt performance eight plus five for total 13.",
      "verdict": "yes"
    },
    "q12_chen": {
      "rationale": "Excludes September 30, 2022 and uses proxy six with the remaining seven and five for total 18.",
      "verdict": "yes"
    },
    "q12_dube": {
      "rationale": "Calculates proxy five, performance 15 and total 18 after three preference points.",
      "verdict": "yes"
    },
    "q12_estrada": {
      "rationale": "Excludes the post-notice October 20 rating and calculates 5+3+5+3=16.",
      "verdict": "yes"
    },
    "q12_farouk_score": {
      "rationale": "Uses the one-rating rule, 3×3=9, with zero preference points, and places Farouk last.",
      "verdict": "yes"
    },
    "q12_tie": {
      "rationale": "Gives Alvarez, Chen, Dube, Estrada, Brandt, Farouk and correctly resolves Chen/Dube by tenure subgroup.",
      "verdict": "yes"
    },
    "q12_protect": {
      "rationale": "Identifies Farouk's restoration protection and applies §351.606(a)(1)–(2) to prevent his release while another employee can be released.",
      "verdict": "yes"
    },
    "q12_released": {
      "rationale": "Identifies exactly Brandt, Estrada and Dube as released from GS-13.",
      "verdict": "yes"
    },
    "q12_assign_dube": {
      "rationale": "Requires GS-12 Gomez, score 17 below Dube's 18, as the least-reduction offer within three grades.",
      "verdict": "yes"
    },
    "q12_assign_estrada": {
      "rationale": "Requires GS-11 Hill, score 14 below 16, and excludes Gomez because his score is 17.",
      "verdict": "yes"
    },
    "q12_assign_brandt": {
      "rationale": "Requires GS-9 Ikeda, excludes the higher-standing holders, and expressly applies Brandt's five-grade disability-preference limit.",
      "verdict": "yes"
    },
    "q12_final": {
      "rationale": "Separates exactly Gomez, Hill and Ikeda; says no GS-13 employee is separated and Jones is unaffected.",
      "verdict": "yes"
    },
    "q12_cite": {
      "rationale": "The scoring, protection and assignment analysis is supported by CFR paragraphs and FR locations.",
      "verdict": "no"
    },
    "q12_fab": {
      "rationale": "No fabricated source is established; the protection period is transparently attributed to the preamble rather than unprinted regulatory text.",
      "verdict": "no"
    }
  },
  "Q13": {
    "q13_valid_1": {
      "rationale": "Three distinct mismatches count: #2 tenure subgroup II's temporary/term exclusion; #5 the automated-self-assessment restriction; and #6 the §351.705 amendment instructions. Both sides are stated and located.",
      "verdict": "yes"
    },
    "q13_valid_2": {
      "rationale": "Three count: #2 temporary/term tenure exclusion, #5 automated-self-assessment restriction, and #6 §351.705 instructions. Thus at least two are valid.",
      "verdict": "yes"
    },
    "q13_valid_3": {
      "rationale": "Three count: #2 temporary/term tenure exclusion, #5 automated-self-assessment restriction, and #6 §351.705 instructions. Thus the three-item threshold is met.",
      "verdict": "yes"
    },
    "q13_valid_4": {
      "rationale": "Only #2, #5 and #6 count. #1 repeats the temporary/time-limited category issue using executive-summary shorthand; #3's review-versus-approval wording does not establish a conflicting requirement; #4 is the excluded five-years-of-the-RIF shorthand.",
      "verdict": "no"
    },
    "q13_valid_6": {
      "rationale": "Only three distinct qualifying mismatches: #2 temporary/term exclusion, #5 automated assessments and #6 §351.705 instructions. The six-item threshold is not met.",
      "verdict": "no"
    },
    "q13_valid_8": {
      "rationale": "Only three distinct qualifying mismatches: #2 temporary/term exclusion, #5 automated assessments and #6 §351.705 instructions. The eight-item threshold is not met.",
      "verdict": "no"
    },
    "q13_valid_10": {
      "rationale": "Only three distinct qualifying mismatches: #2 temporary/term exclusion, #5 automated assessments and #6 §351.705 instructions. The ten-item threshold is not met.",
